def list_order_lines(page: int = 1, page_size: int = 20, field: Optional[str] = None, value: Optional[str] = None, match: str = "equals", fields: Optional[list[str]] = None) -> dict:
    """List order lines, one page at a time. Give field, value and match to filter on one field (equals, contains or startsWith for text).

    page_size is clamped to the range 1 to 100; larger values are reduced, not rejected.

    Args:
        page: Page number, starting at 1 (sent as $skip).
        page_size: Rows per page (1 to 100; sent as $top).
        field: Field to filter on (only typed fields the service allows).
        value: Value to match; it is checked against the field type and written as a typed OData literal.
        match: equals, contains or startsWith (contains and startsWith need a text field; matching is case-sensitive).
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        page = _clamp(page, 1, 1000000)
        page_size = _clamp(page_size, 1, 100)
        sel = _select_fields(fields, _ALLOWED["OrderLine"], _DEFAULT["OrderLine"])
        query = {"$top": page_size, "$skip": (page - 1) * page_size, "$select": ",".join(sel)}
        condition = _odata_filter("OrderLine", field, match, value)
        if condition is not None:
            query["$filter"] = condition
        data = _http_json(_ODATA["OrderLine"]["set"], query)
        rows = _odata_rows(data)[: min(page_size, MAX_RESPONSE_ITEMS)]
        if not rows:
            return _no_results("order_line", "Try fewer filters or a broader search term.")
        results = [_project(row, sel) for row in rows]
        return {"ok": True, "results": results, "count": len(results), "page": page, "page_size": page_size}
    except _Fail as exc:
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


