def lookup_order_line_by_order_id_and_line_number(order_id: int, line_number: int, fields: Optional[list[str]] = None) -> dict:
    """Look up one order line by order id and line number. Says clearly when it does not exist.

    Args:
        order_id: Identifier of the item.
        line_number: Identifier of the item.
        fields: Optional list of field names to return (at most 12; unknown names are ignored).
    """
    try:
        sel = _select_fields(fields, _ALLOWED["OrderLine"], _DEFAULT["OrderLine"])
        data = _http_json(_odata_path("OrderLine", [order_id, line_number]), {"$select": ",".join(sel)})
        item = _odata_item(data)
        if not item:
            return _not_found("order_line", order_id)
        return {"ok": True, "result": _project(item, sel)}
    except _Fail as exc:
        if exc.kind == "not_found":
            return _not_found("order_line", order_id)
        return _fail(exc)
    except Exception:
        return _err("internal", _INTERNAL_MESSAGE)


